<?php
namespace Xdecaro\Component\Decaroevents\Administrator\Model; defined('_JEXEC') or die; use Joomla\CMS\Factory; use Joomla\CMS\MVC\Model\ListModel;
final class RegistrationsModel extends ListModel { protected function populateState($ordering='r.created',$direction='DESC'){parent::populateState($ordering,$direction);$this->setState('filter.search',Factory::getApplication()->input->getString('filter_search'));} protected function getListQuery(){ $db=$this->getDatabase();$q=$db->getQuery(true)->select('r.*, e.title AS event_title, s.title AS session_title')->from($db->quoteName('#__decaroevents_registrations','r'))->join('INNER',$db->quoteName('#__decaroevents_events','e').' ON e.id=r.event_id')->join('LEFT',$db->quoteName('#__decaroevents_sessions','s').' ON s.id=r.session_id');$s=trim((string)$this->getState('filter.search'));if($s!==''){$like=$db->quote('%'.$db->escape($s,true).'%');$q->where('('.$db->quoteName('r.name').' LIKE '.$like.' OR '.$db->quoteName('r.email').' LIKE '.$like.' OR '.$db->quoteName('e.title').' LIKE '.$like.')');}$q->order('r.created DESC');return $q;} }
